function countKmers($seq, $len, $k) {
    $counts = [];
    $end = $len - $k + 1;
    for ($i = 0; $i < $end; $i++) {
        $frag = substr($seq, $i, $k);
        if (isset($counts[$frag])) {
            $counts[$frag]++;
        } else {
            $counts[$frag] = 1;
        }
    }
    return $counts;
}

function printFreq($seq, $len, $k) {
    $counts = countKmers($seq, $len, $k);
    $total = $len - $k + 1;
    // sort by descending count, then by key ascending for stability
    uksort($counts, function($a, $b) use ($counts) {
        $d = $counts[$b] - $counts[$a];
        if ($d !== 0) return $d;
        return strcmp($a, $b);
    });
    $out = '';
    foreach ($counts as $frag => $c) {
        $out .= $frag . ' ' . number_format($c * 100.0 / $total, 3, '.', '') . "\n";
    }
    echo $out . "\n";
}

function countFragment($seq, $len, $frag) {
    $k = strlen($frag);
    $counts = countKmers($seq, $len, $k);
    return $counts[$frag] ?? 0;
}

printFreq($seq, $len, 1);
printFreq($seq, $len, 2);

