        }
        // (q, r, t, k, n, l)
        // nr = 10*(r - n*t)
        $nr = gmp_mul(gmp_sub($r, gmp_mul($nn, $t)), 10);
        // nn = ((10*(3*q+r))/t) - 10*n
        $nn = gmp_sub(gmp_div_q(gmp_mul(gmp_add(gmp_mul($q, 3), $r), 10), $t), gmp_mul($nn, 10));
        $q = gmp_mul($q, 10);
        $r = $nr;
    } else {
        // nr = (2*q+r)*l
        $nr = gmp_mul(gmp_add(gmp_mul($q, 2), $r), $l);
        // nn = (q*(7*k)+2+r*l)/(t*l)
        $nn = gmp_div_q(gmp_add(gmp_add(gmp_mul($q, gmp_mul($k, 7)), 2), gmp_mul($r, $l)), gmp_mul($t, $l));
        $q = gmp_mul($q, $k);
        $t = gmp_mul($t, $l);
        $l = gmp_add($l, 2);
        $k = gmp_add($k, 1);
        $r = $nr;
    }
}

// handle remainder if n not multiple of 10
if ($n % 10 !== 0) {
    $rem = $n % 10;
    $pad = 10 - $rem;
    $out .= str_repeat(' ', $pad) . "\t:" . $n . "\n";
}

